#include <stdio.h>

int main(void) {
    int S, T;
    scanf("%d %d", &S, &T);

    static unsigned char adj[1005][1005] = {0};

    for (int i = 0; i < T; i++) {
        int X, Y;
        scanf("%d %d", &X, &Y);
        adj[X][Y] = 1;
        adj[Y][X] = 1;
    }

    int P;
    scanf("%d", &P);

    int answer = 0;

    for (int q = 0; q < P; q++) {
        int N;
        scanf("%d", &N);

        int prev = -1;
        int possible = 1;

        for (int i = 0; i < N; i++) {
            int c;
            scanf("%d", &c);

            if (i > 0 && !adj[prev][c]) {
                possible = 0;
            }

            prev = c;
        }

        if (possible) {
            answer++;
        }
    }

    printf("%d\n", answer);

    return 0;
}
